exec("from sqlalchemy import ForeignKey, create_engine, select\nfrom sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, relationship, Session, selectinload\nclass Base(DeclarativeBase):\n    pass\nclass Entity(Base):\n    __tablename__ = 'Entity'\n    id: Mapped[int] = mapped_column(primary_key=True)\n    relationship_attribute: Mapped[list['Child']] = relationship(back_populates='parent')\nclass Child(Base):\n    __tablename__ = 'relationship_attribute'\n    id: Mapped[int] = mapped_column(primary_key=True)\n    parent_id: Mapped[int] = mapped_column(ForeignKey('Entity.id'))\n    parent: Mapped[Entity] = relationship(back_populates='relationship_attribute')\nengine = create_engine('sqlite://', echo=True)\nBase.metadata.create_all(engine)\nwith Session(engine) as session:\n    session.add_all([Entity(id=11),Entity(id=22),Entity(id=33),\n                     Child(id=111,parent_id=11),Child(id=112,parent_id=11),Child(id=221,parent_id=22)])\n    session.commit()\n")
statement = select(Entity).options(selectinload(Entity.relationship_attribute))
exec("\nimport io, logging\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\ndef audit_listing(take):\n    stream=io.StringIO()\n    handler=logging.StreamHandler(stream)\n    logger=logging.getLogger('sqlalchemy.engine.Engine')\n    logger.addHandler(handler)\n    with Session(engine) as session:\n        parents=session.execute(select(Entity).order_by(Entity.id).limit(take)).scalars().all()\n        before=[{'id':p.id,'children':[child.id for child in p.relationship_attribute]} for p in parents]\n    before_sql=stream.getvalue();stream.seek(0);stream.truncate(0)\n    with Session(engine) as session:\n        parents=session.execute(statement.order_by(Entity.id).limit(take)).scalars().all()\n        after=[{'id':p.id,'children':[child.id for child in p.relationship_attribute]} for p in parents]\n    after_sql=stream.getvalue()\n    logger.removeHandler(handler)\n    return {'before':before,'after':after,'before_selects':before_sql.count('SELECT '),'after_selects':after_sql.count('SELECT ')}\n")

import json
print('RESULT='+json.dumps([audit_listing(2),audit_listing(3)]))
